{{documentation}}
Powers most exchange pages and exchange-related modules and templates.
{{Helper module|name=Exchange |fname1=_price(arg) |ftype1=String |fuse1=Gets the current GE price of item named arg |fname2=_price(arg, multi, format, round, default) |ftype2=String |fuse2=Gets the current GE price of item named arg, multiplied by [multi] (default 1), rounded to [round] decimal places (default unrounded), and if [format] is true, formatted with thousands separators (default false). If the item does not exist, an error is thrown, unless [default] is set, in which case it will return the given [default] value. |fname3=_value(arg) |ftype3=String |fuse3=Gets the value of item named arg |fname4=_highalch(arg) |ftype4=String |fuse4=Gets the high alch value of item named arg, accounting for alch multipliers |fname5=_lowalch(arg) |ftype5=String |fuse5=Gets the low alch value of item named arg, accounting for alch multipliers |fname6=_alchable(arg) |ftype6=String |fuse6=Gets the alchablility (boolean) of item named arg |fname7=_alchmultiplier(arg) |ftype7=String |fuse7=Gets the alchemy multiplier of item named arg (default 0.6) |fname8=_limit(arg) |ftype8=String |fuse8=Gets the GE limit of item named arg |fname9=_diff(arg, format) |ftype9=String |fuse9=Gets the difference of the current GE price and the previous GE price for item named arg. If format is true, formats the number with thousands separators |fname10=_exists(arg) |ftype10=String |fuse10=Checks if the module for item named arg exists, returns a boolean }}

local p = {}
-- Collected food rows on the page local foods = {}
-- Called once per food to register it function p.add(frame) local name = frame.args.name local heal = tonumber(frame.args.heal) local gpph = tonumber(frame.args.gpph)
-- Skip unevaluable rows (random heals, special effects, etc.) if not name or not heal or not gpph then return '' end
table.insert(foods, { name = name, heal = heal, gpph = gpph, row = frame.args.row })
return '' end
-- Strict dominance check local function isDominated(a, list) for _, b in ipairs(list) do if b ~= a then if b.heal >= a.heal and b.gpph < a.gpph then return true end end end return false end
-- Emit all rows with efficiency flag function p.render(frame) local out = {}
for _, food in ipairs(foods) do local dominated = isDominated(food, foods)
local class = dominated and 'food-inefficient' or 'food-efficient' local label = dominated and '❌ Inefficient' or '✔️ Efficient'
table.insert(out, string.format( '|- class="%s"\n%s\n| %s', class, food.row, label ) ) end
return table.concat(out, '\n') end
return p

local p = {}
function p.signed(arg) local first_char = string.sub(arg, 1, 1)
if first_char == '+' or first_char == '-' then return arg else return '+'..arg end end
function p.main(frame) local args = frame:getParent().args
local arg = args[1] or '' return p.signed(arg) end
return p

local p = {}

function p.main(frame)
	return p.format(frame:getParent().args[1])
end

function p.format(_arg, default)
	local arg = tonumber(_arg)
	if not arg then return default or _arg end
	if arg < 0 then return tostring(arg) end
	return '+'..arg
end

return p

{{Documentation}}
<code>main</code> takes a single unnamed argument that is the items name and returns the GE Limit of the item, or 0 if the item is not found.

<code>table</code> Generates tables of all the GE Limits, with <code>==</code> sections for ''#'' and each letter.

--<nowiki>
local arr = require("Module:Array")
local Coins = require("Module:Coins")._amount
local ExchangeData = require("Module:ExchangeData")
local p = {}

function p.items(num)
	local prices = mw.loadJsonData("Module:GEPrices/data.json")
	local prices_a = {}
	for k, v in pairs(prices) do
		if string.sub(k, 1, 1) ~= '%' then
			table.insert(prices_a, {item=k, price=v or -1})
		end
	end
	table.sort(prices_a, function(a, b) return a.price > b.price end)
	return arr.slice(prices_a, 1, num)
end

function p._chart(items)
	return ExchangeData._chart({table.concat(items, ",")})
end

function p.chart(frame)
	local count = frame.args ~= nil and tonumber(frame.args.count) or 10
	return p._chart(arr.map(p.items(count), function(item) return item.item end))
end

function p._list(items)
	local t = {}
	for _, pair in ipairs(items) do
		table.insert(t, string.format("* [[%s]] (%s)", pair.item, Coins(pair.price), item['Members']))
	end
	return table.concat(t, "\n")
end

function p.list(frame)
	local count = frame.args ~= nil and tonumber(frame.args.count) or 100
	return p._list(p.items(count))
end

function p._table(items)
	local t = {
		'{|class="wikitable align-center-1"\n' ..
		'! colspan="2" | Item\n' ..
		'! Price\n' ..
		'! [[File:Member icon.png|link=|Members]]'
	}

	for _, pair in ipairs(items) do
		table.insert(t, string.format(
			"| [[File:%s.png|link=%s|class=inventory-image]] || [[%s]] || %s", pair.item, pair.item, pair.item, Coins(pair.price), pair.item['Members']
		))
	end
	return table.concat(t, "\n|-\n") .. "\n|}"
end

function p.table(frame)
	local count = frame.args ~= nil and tonumber(frame.args.count) or 100
	return p._table(p.items(count))
end

function p.main(frame)
	local args = frame:getParent().args
	local count = args.count or 10
	local items = p.items(count)
	return p.chart(arr.map(items, function(item) return item.item end))
end

return p
--</nowiki>

-- <nowiki> local prices = mw.loadJsonData('Module:GEPrices/data.json') local _coins = require('Module:Currency')._amount local p = {}
local fmap = { wikitable = 'wikitable', wikitablereverse = 'wikitablereverse', table = 'wikitable', t = 'wikitable', rtable = 'wikitablereverse', rt = 'wikitablereverse', bracket = 'bracket', b = 'bracket', backetreverse = 'backetreverse', rb = 'backetreverse', item = 'item', price = 'price', none = 'none' }
local formats = { wikitable = function(i,v) return string.format('| %s\n| %s', i, v) end, wikitablereverse = function(i,v) return string.format('| %s\n| %s', v, i) end, bracket = function(i,v) return string.format('%s (%s)', i, v) end, backetreverse = function(i,v) return string.format('%s (%s)', v, i) end, item = function(i,v) return i end, price = function(i,v) return v end, none = function(i,v) return '' end }
function findVal(comp, def, args) local item = '@unknown@' local value = def for i,v in ipairs(args) do local pr = prices[v] if pr then if comp(pr, value) then value = pr item = v end end end return item, value end
function p._min(args) return findVal(function(pr,v) return v > pr end, math.huge, args) end function p._max(args) return findVal(function(pr,v) return v < pr end, -1, args) end
function p.main(frame) local c = frame.args[1] local pargs = frame:getParent().args local f = fmap[pargs.format] f = formats[f] or formats.bracket local r1, r2 = p['_'..c](pargs) if pargs.coins == 'y' then r2 = _coins(r2, 'coins') elseif pargs.coins == 'n' then r2 = _coins(r2, 'nocoins') elseif pargs.coins == 'f' then r2 = mw.getContentLanguage():formatNum(r2) end if pargs.link == 'plp' then r1 = string.format('[[File:%s.png|link=%s]]', r1, r1) elseif pargs.link == 'p' then r1 = string.format('[[File:%s.png|link=%s]] [[%s]]', r1, r1, r1) elseif not pargs.link then r1 = string.format('[[%s]]', r1) end
if pargs.var then mw.ext.VariablesLua.vardefine(pargs.var..'_item', r1) mw.ext.VariablesLua.vardefine(pargs.var..'_price', r2) end
return f(r1, r2) end
return p -- </nowiki>

