		{ name = 'players', func = 'has_content' },
		{ name = 'skills', func = 'has_content' },
		{ name = 'requirements', func = 'has_content' },
		{ name = 'currency', func = 'has_content' },
		{ name = 'tutorial', func = 'has_content' },
		{ name = 'music', func = 'has_content' },
