	return ret:tostring()
end

function cost_bucket(arg)
	--The input is a fully parsed {{RuneReq}}. Grab the link targets.
	local materials = {}
	-- Pattern to match the link target produced by {{RuneReq}}
	for m in string.gmatch(arg, '%[%[[^|]+%|[^|]+%|link=([^|%]]+)%]%]') do
		table.insert(materials, m)
	end

	return materials
end

function json_bucket(level, slayerlevel, exp, cost, spell_type, spellbook)
	local json = {
		level = level,
		slayerlevel = slayerlevel,
		exp = exp,
		cost = cost,
		type = spell_type,
		spellbook = spellbook
	}
	return mw.text.jsonEncode(json)
end

function level(arg)
	if not infobox.isDefined(arg) then
		return nil
	end
	return skillpic("Magic", arg )
end

function slayerlevel(arg)
	if not infobox.isDefined(arg) then
		return nil
	end

	return skillpic("Slayer", arg )
end

function spellbook(arg)
	if not infobox.isDefined(arg) then
		return nil
	end

	local function link(s)
		if s == 'normal' then
			return "[[Standard spellbook|Standard]]"
		end
		if s == 'ancient' then
			return "[[Ancient Magicks|Ancient]]"
		end
		if s == 'lunar' then
			return "[[Lunar spellbook|Lunar]]"
		end
		if s == 'arceuus' then
			return "[[Arceuus spellbook|Arceuus]]"
		end
		if s == 'all' then
			local all = { link('normal'), link('ancient'), link('lunar'), link('arceuus') }
			return table.concat(all, "<br>")
		end
	end

	return link(string.lower(arg))
end

function spell_type(arg)
	if not infobox.isDefined(arg) then
		return nil
	end
	arg = string.lower(arg)
	if arg == 'combat' then
		return "[[Combat spells|Combat]]"
	end
	if arg == 'teleport' then
		return "[[Teleportation spells|Teleport]]"
	end
	if arg == 'utility' then
		return "[[Utility spells|Utility]]"
	end
end

function element(arg)
	if not infobox.isDefined(arg) then
		return nil
	end

	return "[[" .. arg .. " spells|" .. arg .. "]]"
end

function quest(quest, spellbook)
	spellbook = string.lower(spellbook)
	if infobox.isDefined(quest) then
		if spellbook == 'ancient' then
			return quest .. "<br>(plus [[Desert Teasure I]])"
		end
		return quest
	end

	if spellbook == 'ancient' then
		return "[[Desert Treasure I]]"
	end
	if spellbook == 'lunar' then
		return "[[Lunar Diplomacy]]"
	end
end

function addcategories(args, catargs)
	local ret = { 'Spells' }

 	-- Add the associated category if the parameter has content
	local defined_args = {
		cooldown = 'Spells with cooldowns',
	}
	for n, v in pairs(defined_args) do
		if catargs[n] and catargs[n].one_defined then
			table.insert(ret, v)
		end
	end

 	-- Add the associated category if the parameter doesn't have content
 	local notdefined_args = {
 		image = 'Needs image',
 		release = 'Needs release date',
 		update = 'Needs update',
 		members = 'Needs members status',
 		exp = 'Needs experience info',
 		sound = 'Needs sound effect added'

 	}
	for n, v in pairs(notdefined_args) do
		if catargs[n] and catargs[n].all_defined == false then
			table.insert(ret, v)
		end
	end

    -- release year
    local year = args.release.d:match('%d%d%d%d')
    if year then
        table.insert(ret, 'Content released in '..year)
    end
    if args.release.switches then
        for _, v in ipairs(args.release.switches) do
            year = v:match('%d%d%d%d')
            if year then
                table.insert(ret, 'Content released in '..year)
            end
        end
    end

	local cat_map = {
		-- Parameters that have text
		-- map a category to a value
		matches = {
			members = { yes = 'Members\' spells', no = 'Free-to-play spells' },
		}
	}

	-- searches
	for n, v in pairs(cat_map.matches) do
		for m, w in pairs(v) do
			if args[n] then
				if string.lower(tostring(args[n].d) or '') == m then
					table.insert(ret, w)
				end
			end
		end
	end

	-- combine table and format category wikicode
	for i, v in ipairs(ret) do
		if (v ~= '') then
			ret[i] = string.format('[[Category:%s]]', v)
		end
	end

	return table.concat(ret, '')
end

return p

-- Module for [[Template:Weapon group]]

local p = {}

local infobox = require('Module:Infobox')

-- Format attack speed
function attackspeedarg(arg)
	if not infobox.isDefined(arg) then
		return nil
	end

	local lowarg = string.lower(arg)
	local numarg = tonumber(arg)

	if lowarg == 'no' or lowarg == 'n/a' then
		return 'N/A'
	elseif lowarg == 'varies' or lowarg == 'random' then
		return '<span title="Weapons in this group have a variable attack speed." style="cursor:help; border-bottom:1px dotted;">Variable</span>'
	end

	if numarg ~= nil then
		return string.format('%s %s (%.1f seconds)', numarg, (numarg > 1) and 'ticks' or 'tick', numarg * 0.6)
	end	
end

-- Main function called with invokes
function p.main(frame)
	local args = frame:getParent().args
	local ret = infobox.new(args)

	ret:defineParams{
		{ name = 'name', func = 'name' },
		{ name = 'images', func = 'has_content' },
		{ name = 'primary', func = 'has_content' },
		{ name = 'secondary', func = 'has_content' },
		{ name = 'tertiary', func = 'has_content' },
		{ name = 'speed', func = attackspeedarg },
	}

	ret:defineLinks({ hide = true })

	ret:create()
	ret:cleanParams()

	ret:defineName('Infobox Weapon Group')

	ret:addRow{
		{ tag = 'argh', content = 'name', class='infobox-header', colspan = '20' }
	}
	ret:pad(20)
	ret:addRow{
		{ tag = 'argd', content = 'images', class='infobox-image', colspan = '20' }
	}
	ret:pad(20)
	ret:addRow{
		{ tag = 'th', content = 'Primary [[Attack type|type]]', colspan = '7' },
		{ tag = 'argd', content = 'primary', colspan = '13' }
	}

	ret:addRow{
		{ tag = 'th', content = 'Secondary [[Attack type|type]]', colspan = '7' },
		{ tag = 'argd', content = 'secondary', colspan = '13' }
	}

	if ret:paramDefined('tertiary') then
		ret:addRow{
			{ tag = 'th', content = 'Tertiary [[Attack type|type]]', colspan = '7' },
			{ tag = 'argd', content = 'tertiary', colspan = '13' }
		}
	end

	ret:pad(20)
	ret:addRow{
		{ tag = 'th', content = '[[Attack speed]]', class = 'infobox-subheader', colspan = '20' }
	}
	ret:pad(20)
	ret:addRow{
		{ tag = 'argd', content = 'speed', colspan = '20', class = 'infobox-full-width-content' }
	}
	ret:pad(20)

	return ret:tostring()
end

return p

local IDListUtils = require('Module:IDListUtils')
local p = {}
function p.render() local bucketName = 'item_id' local results = IDListUtils.fetchResults(bucketName)
local output = { 'Total number of items in this table: ' .. #results .. '.', '{| class="sortable wikitable"', '!Item', '![[Bucket:' .. bucketName .. '|Item IDs]]' }
table.sort(results, function(a,b) return a.page_name_sub < b.page_name_sub end )
for _, result in ipairs(results) do local ids = IDListUtils.linkIds('item', result.id)
table.insert(output, '|-') table.insert(output, '|[[' .. result.page_name_sub..']]') table.insert(output, '|' .. ids) end
table.insert(output, '|}')
return table.concat(output, '\n') end
return p

-- <pre> require('strict') local p = {}
-- from <https://en.wikipedia.org/w/index.php?title=Module:Key&oldid=1071502366> local keyText = { ['caps lock'] = '⇪ Caps Lock', -- ['[[caps lock]]'] = '⇪ [[Caps Lock]]', ['shift'] = '⇧ Shift', -- ['[[shift key|shift]]'] = '⇧ [[Shift key|Shift]]', ['enter'] = '↵ Enter', -- ['[[enter key|enter]]'] = '↵ [[Enter key|Enter]]', ['cmd'] = '⌘ Cmd', -- ['[[command key|cmd]]'] = '⌘ [[Command key|Cmd]]', ['command'] = '⌘ Command', -- ['[[command key|command]]'] = '⌘ [[Command key|Command]]', ['opt'] = '⌥ Opt', -- ['[[option key|opt]]'] = '⌥ [[Option key|Opt]]', ['option'] = '⌥ Option', -- ['[[option key|option]]'] = '⌥ [[Option key|Option]]', ['tab'] = 'Tab ↹', -- ['[[tab key|tab]]'] = '[[Tab key|Tab]] ↹', ['backspace'] = '← Backspace', -- ['[[backspace]]'] = '← [[Backspace]]', ['win'] = '⊞ Win', -- ['[[windows key|win]]'] = '⊞ [[Windows key|Win]]', ['menu'] = '≣ Menu', -- ['[[menu key|menu]]'] = '≣ [[Menu key|Menu]]', ['up'] = '↑', -- ['[[arrow keys|up]]'] = '[[Arrow keys|↑]]', ['down'] = '↓', -- ['[[arrow keys|down]]'] = '[[Arrow keys|↓]]', ['left'] = '←', -- ['[[arrow keys|left]]'] = '[[Arrow keys|←]]', ['right'] = '→', -- ['[[arrow keys|right]]'] = '[[Arrow keys|→]]', ['asterisk'] = '&#42;', ['hash'] = '&#35;', -- ['[[#]]'] = '[[Number sign|#]]', ['colon'] = '&#58;', -- ['[[:]]'] = '[[Colon (punctuation)|:]]', ['pipe'] = '&#124;', -- ['[[|]]'] = '[[Pipe symbol|&#124;]]', ['semicolon'] = '&#59;', -- ['[[;]]'] = '[[Semi-colon|&#59;]]', ['equals'] = '&#61;' }
local keyAlias = { -- ['alternate name for key (alias)'] = 'name for key used in key table' -- ['[[cmd key|cmd]]'] = '[[command key|cmd]]', -- ['[[cmd key|command]]'] = '[[command key|command]]', -- ['[[opt key|opt]]'] = '[[option key|opt]]', -- ['[[option key]]'] = '[[option key|option]]', -- ['[[opt key|option]]'] = '[[option key|option]]', -- ['[[win key|win]]'] = '[[windows key|win]]', ['*'] = 'asterisk', ['#'] = 'hash', [':'] = 'colon', [';'] = 'semicolon' }
function p._main(args) local ret = mw.html.create('span') :css('white-space','nowrap')
local sep = args.sep or '+' local keys = {} local tblsize = 0
for i, v in ipairs(args) do tblsize = i table.insert(keys,v) end
for i, v in ipairs(keys) do local lc = v:lower() local text = keyText[lc] or keyText[keyAlias[lc]] or v ret :tag('kbd') :addClass('keypress') :wikitext(text) :done()
if i < tblsize then ret:wikitext(sep) end end
return tostring(ret) end
function p.main(frame) local args = frame:getParent().args return p._main(args) end
return p

local p = {}
local build_map = require('Module:Map').buildMap local default_to = require('Module:Paramtest').default_to
local bad_chars = {'%(', '%)', '%s'}
function p.main(frame) local args = frame.args local page_name = args.page_name
local data = bucket('locline') .select('coordinates') .where('page_name', page_name) .run()
local page_name_clean = page_name for _, bad_char in ipairs(bad_chars) do page_name_clean = page_name_clean:gsub(bad_char, '') end
local map_args = { ['type'] = 'maplink', ['mtype'] = 'pin', ['icon'] = default_to(args['icon'], 'redPin'), ['text'] = default_to(args['text'], 'Map'), ['mapID'] = default_to(args['mapID'], 0), ['title'] = '[[' .. page_name .. ']]', ['group'] = page_name_clean, }
local i = 1 for _, row in ipairs(data) do if row['coordinates'] ~= nil then for _, coord_string in ipairs(row['coordinates']) do map_args[i] = coord_string i = i + 1 end end end
return build_map(map_args) end
return p

{{documentation}}
{{Helper module|name=Mainonly
|fname1=_main(arg)
|ftype1=Any value
|fuse1=If the module is invoked in the content namespace, it will return arg, otherwise, it will return an empty string
