local Paramtest = require( 'Module:Paramtest' ) local Slayerlib = require ('Module:Slayer_task_library' ) local SlayerConsts = require('Module:SlayerConsts')
local p = {}
function p.invoke_main( frame ) local result = p.main( frame:getParent().args )
return result end
function p.tobool(str) if str == 'true' then return true end return false end
function p.main( args ) -- Handle inputs local desiredTask = Paramtest.defaults{ { args.wantedTask, 'None' } }
local combatLevel, slayerLevel, defenceLevel, agilityLevel, rangedLevel, strengthLevel, hitpointsLevel, thievingCheck, firemakingCheck, magicCheck = Paramtest.defaults{ { tonumber(args.combatLevel), 1 }, { tonumber(args.slayerLevel), 1 }, { tonumber(args.defenceLevel), 1 }, { tonumber(args.agilityLevel), 1 }, { tonumber(args.rangedLevel), 1 }, { tonumber(args.strengthLevel), 1 }, { tonumber(args.hitpointsLevel), 10 }, { args.thievingCheck, true }, { args.firemakingCheck, true }, { args.magicCheck, true } }
local block1, block2, block3, block4, block5, block6 = Paramtest.defaults{ { args.block1, 'None'}, { args.block2, 'None'}, { args.block3, 'None'}, { args.block4, 'None'}, { args.block5, 'None'}, { args.block6, 'None'}, }
local blocks = { block1, block2, block3, block4, block5, block6 }
-- Magic number 23 since this is the highest level required for thieving (magic axes) local thievingLevel = 23 if p.tobool(thievingCheck) == false then thievingLevel = 1 end
-- Magic number 33 since this is the highest level required for firemaking local firemakingLevel = 33 if p.tobool(firemakingCheck) == false then firemakingLevel = 1 end
-- Magic number 50 since this is the highest level required for magic local magicLevel = 50 if p.tobool(magicCheck) == false then magicLevel = 1 end
-- Need to create a stats table, unlocks table, quests table, and other table local stats = { Combat = combatLevel, Slayer = slayerLevel, Magic = magicLevel, Agility = agilityLevel, Strength = strengthLevel, Firemaking = firemakingLevel, Defence = defenceLevel, Hitpoints = hitpointsLevel, Ranged = rangedLevel, Thieving = thievingLevel }
-- Since the checkboxes return the name of the unlock (same as in UNLOCK_IDS) -- if checked and nil if not checked, this array will only be the names of -- activated unlocks. local unlocks = { args.seeingRed, args.iHopeYouMithMe, args.watchTheBirdie, args.hotStuff, args.reptileGotRipped, args.likeABoss, args.stopTheWyvern, args.basilocked, args.unlockedVamps, args.iWildyMoreSlayer, args.WarpedReality }
-- Similarly, this will become a list of completed quests. local quests = { args.priestInPeril, args.dragonSlayerII, args.dragonSlayer, args.cabinFever, args.horrorFromTheDeep, args.mourningsEndPartII, args.desertTreasure, args.regicide, args.boneVoyage, args.lostCity, args.elementalWorkshopI, args.deathPlateau, args.lunarDiplomacy, args.olafsQuest, args.contact, args.rumDeal, args.skippyAndTheMogres, args.deathToTheDorgeshuun, args.legendsQuest, args.ernestTheChicken, args.royalTrouble, args.hauntedMine, args.porcineOfInterest, args.SecretsOfTheNorth, args.DesertTreasure2, args.perilousMoons, args.shadowsOfCustodia }
-- List of completed other activities. local accessGWD = nil if stats["Strength"] >= 60 or stats["Agility"] >= 60 then accessGWD = 'Access GWD' end local other = { args.ancientCavern, accessGWD, args.brittleKey, args.accessAbyss }
-- Handle specific tasks that can actually have 2 assignments
-- Create the player status given our various inputs status = Slayerlib.create_status(stats, quests, unlocks, other, blocks)
-- Add skeleton hellhounds, demonic gorillas, and any other multi-task enemies to this list -- Vorkath may need to be updated with zombie -- I doubt Zulrah is a sea snake
-- What makes a monster "special"? -- A monster should be considered "special" if it is not a direct task but -- there is a valid reason for wanting to kill it. -- Bosses are not considered a direct task, the "Boss" task is the direct task. -- Therefore, this table will be largely subjective.
-- Tasks like Demonic Gorillas could be considered special since there is a -- reason to kill them, but Demonic Gorillas themselves are not a task.
-- On the other hand, tasks like Undead Chickens *could* be considered special -- since they count for both Zombie and Chicken tasks, but is there a reason -- to actually want them as a task? Adding them for completion could be nice -- but given how unwieldy the calc already is, this seems like a bad idea.
