specialNameTable = { [SlayerConsts.TASK_BOSS_ABYSSAL_SIRE] = "[[Abyssal Sire]]", [SlayerConsts.TASK_BOSS_ARAXXOR] = "[[Araxxor]]", [SlayerConsts.TASK_BOSS_ALCHEMICAL_HYDRA] = "[[Alchemical Hydra]]", [SlayerConsts.TASK_BOSS_BARROWS] = "[[Barrows]]", [SlayerConsts.TASK_BOSS_CALLISTO] = "[[Callisto]]", [SlayerConsts.TASK_BOSS_CERBERUS] = "[[Cerberus]]", [SlayerConsts.TASK_BOSS_CHAOS_ELEMENTAL] = "[[Chaos Elemental]]", [SlayerConsts.TASK_BOSS_CHAOS_FANATIC] = "[[Chaos Fanatic]]", [SlayerConsts.TASK_BOSS_COMMANDER_ZILYANA] = "[[Commander Zilyana]]", [SlayerConsts.TASK_BOSS_CRAZY_ARCHAEOLOGIST] = "[[Crazy archaeologist]]", [SlayerConsts.TASK_BOSS_DAGANNOTH_KINGS] = "[[Dagannoth Kings]]", [SlayerConsts.TASK_BOSS_GENERAL_GRAARDOR] = "[[General Graardor]]", [SlayerConsts.TASK_BOSS_GIANT_MOLE] = "[[Giant Mole]]", [SlayerConsts.TASK_BOSS_GROTESQUE_GUARDIANS] = "[[Grotesque Guardians]]", [SlayerConsts.TASK_BOSS_KRIL_TSUTSAROTH] = "[[K'ril Tsutsaroth]]", [SlayerConsts.TASK_BOSS_KALPHITE_QUEEN] = "[[Kalphite Queen]]", [SlayerConsts.TASK_BOSS_KING_BLACK_DRAGON] = "[[King Black Dragon]]", [SlayerConsts.TASK_BOSS_KRAKEN] = "[[Kraken]]", [SlayerConsts.TASK_BOSS_KREEARRA] = "[[Kree'arra]]", [SlayerConsts.TASK_BOSS_SARACHNIS] = "[[Sarachnis]]", [SlayerConsts.TASK_BOSS_SCORPIA] = "[[Scorpia]]", [SlayerConsts.TASK_BOSS_THERMONUCLEAR_SMOKE_DEVIL] = "[[Thermonuclear smoke devil]]", [SlayerConsts.TASK_BOSS_VENENATIS] = "[[Venenatis]]", [SlayerConsts.TASK_BOSS_VETION] = "[[Vet'ion]]", [SlayerConsts.TASK_BOSS_VORKATH] = "[[Vorkath]]", [SlayerConsts.TASK_BOSS_ZULRAH] = "[[Zulrah]]", [SlayerConsts.TASK_SKOTIZO] = "[[Skotizo]]", [SlayerConsts.TASK_DEMONIC_GORILLAS] = "[[Demonic gorilla]]s", [SlayerConsts.TASK_SKELETON_HELLHOUNDS] = "[[Skeleton Hellhound (Vet'ion)]]", [SlayerConsts.TASK_REVENANTS] = "[[Revenant]]s" }
local monstersToSearch = {} if specialTable[SlayerConsts.get_monster_id(desiredTask)] ~= nil then for _, id in ipairs(specialTable[SlayerConsts.get_monster_id(desiredTask)]) do table.insert(monstersToSearch, SlayerConsts.get_monster_name(id)) end else table.insert(monstersToSearch, desiredTask) end
local taskPercents = {} local taskName = '' if specialTable[SlayerConsts.get_monster_id(desiredTask)] ~= nil then taskName = specialNameTable[SlayerConsts.get_monster_id(desiredTask)] end for _, monsterToSearch in ipairs(monstersToSearch) do -- Get all masters that can assign this task. slayerMasters = Slayerlib.get_masters_that_assign(monsterToSearch)
-- Get the entire task table of the chosen slayer master. for slayerMaster, _ in pairs(slayerMasters) do local masterTable = Slayerlib.get_table(slayerMaster)
-- If this is the actual monster we are looking for, grab the name from the table if monsterToSearch == desiredTask and taskName == '' then taskName = masterTable[SlayerConsts.get_monster_id(monsterToSearch)]['name'] end
-- Get the tables of available and unavailable tasks. local effectiveTable, unavailableTable = Slayerlib.get_effective_table(masterTable, status, true)
-- Pass these to calculate percents. if taskPercents[slayerMaster] == nil then taskPercents[slayerMaster] = p.calculate_percent(effectiveTable, monsterToSearch) else taskPercents[slayerMaster] = taskPercents[slayerMaster] + p.calculate_percent(effectiveTable, monsterToSearch) end end end
-- Render the results return p.render_table(taskPercents, taskName) end
-- -- Calculates the percent chance of getting each task from effectiveTable. -- -- @param effectiveTable {table} A table of all tasks the player can be assigned. -- @param unavailableTable {table} A table of all tasks the player cannot be assigned. -- -- @return {table} Returns a table that contains the task name as key and the -- percent chance (decimal form) of getting it as the value. -- function p.calculate_percent(effectiveTable, desiredTask) local totalWeight = 0 for k, v in pairs(effectiveTable) do totalWeight = totalWeight + v['weight'] end
for k, v in pairs(effectiveTable) do if v['subtable'] ~= nil then subtablePercents = p.calculate_percent(v['subtable'], desiredTask) if subtablePercents ~= 0 then subtableMult = v['weight']/totalWeight return subtableMult*subtablePercents end end if k == Slayerlib.get_monster_id(desiredTask) then return v['weight']/totalWeight end end
return 0 end
function pairs_by_keys(t, f) local a = {} for n in pairs(t) do table.insert(a, n) end table.sort(a, f) local i = 0 -- iterator variable local iter = function () -- iterator function i = i + 1 if a[i] == nil then return nil else return a[i], t[a[i]] end end return iter end
-- Render the results table. function p.render_table(results, desiredTask) local resultsDiv = mw.html.create( 'div' ) local resultsTable = mw.html.create( 'table' ) resultsTable:addClass( 'wikitable' ) :addClass( 'sortable') :addClass( 'align-center-1' ) :tag( 'tr' ) :tag( 'th' ) :wikitext( 'Results for ' .. desiredTask ) :attr( 'colspan', 2 ) :done() :done() :tag( 'tr' ) :tag( 'th' ) :wikitext( 'Master' ) :done() :tag( 'th' ) :wikitext( 'Assignment Chance') :done() :done() :done()
for k, v in pairs_by_keys(results) do resultsTable:tag( 'tr' ) :tag( 'td' ) :wikitext( k ) :done() :tag( 'td' ) :wikitext( string.format("%.2f", 100*v ) .. "%") :attr( 'align', 'right' ) :done() :done() end
resultsDiv:node(tostring(resultsTable)) return resultsDiv end
return p

