--<nowiki>
local p = {}

function p.multi(str, count)
	return string.rep(str, count)
end

function p.main(frame)
	local args = frame:getParent().args
	local str = args[1]
	local times = args[2] or 2
	return p.multi(str, times)
end

return p
--</nowiki>

-- This module is detached from the NA template.
-- It's purpose is to provide an identical feature for modules
-- building tables with the Scribunto HTML library.

local p = {}

-- Create a new node with the content and style
function p.createNode(text)
	return configure(mw.html.create('td'), text)
end

-- Add the content and style to an existing node
function p.styleNode(htmlNode, text)
	configure(htmlNode, text)
end

-- Create a new node, to be used with Module:Tables
function p.rowNode(text)
	return {
		text = text,
		class = 'table-na nohighlight',
		css = {['text-align'] = 'center'}
	}
end

function configure(node, text)
	return node
		:wikitext(text)
		:attr('class', 'table-na nohighlight')
		:attr('style', 'text-align:center;')
end

return p

local IDListUtils = require('Module:IDListUtils')
local p = {}
function p.render() local bucketName = 'npc_id' local results = IDListUtils.fetchResults(bucketName)
local output = { 'Total number of NPCs in this table: ' .. #results .. '.', '{| class="sortable wikitable"', '!Item', '![[Bucket:' .. bucketName .. '|NPC IDs]]' }
table.sort(results, function(a,b) return a.page_name_sub < b.page_name_sub end )
for _, result in ipairs(results) do local ids = IDListUtils.linkIds('npc', result.id)
table.insert(output, '|-') table.insert(output, '|[[' .. result.page_name_sub..']]') table.insert(output, '|' .. ids) end
table.insert(output, '|}')
return table.concat(output, '\n') end
return p

