local p = {}

local onmain = require('Module:Mainonly').on_main
local infobox = require('Module:Infobox')

local banktype_categories = {
	booth = 'Booths',
	chest = 'Chests',
	backpackbank = 'Backpack Banks',
	other = 'Other banks',

}

-- Main function called with invokes
function p.main(frame)
	local args = frame:getParent().args
	local ret = infobox.new(args)

	ret:defineParams{
		{ name = 'name', func = 'name' },
		{ name = 'image', func = 'image' },
		{ name = 'release', func = 'release' },
		{ name = 'aka', func = 'has_content' },
		{ name = 'members', func = 'has_content' },
		{ name = 'floors', func = 'has_content' },
		{ name = 'location', func = 'has_content' },
		{ name = 'music', func = 'has_content' },
		{ name = 'depositbox', func = 'has_content'},
		{ name = 'pollbooth', func = 'has_content'},
		{ name = 'tellers', func = 'has_content'},
		{ name = 'map', func = maparg },
        { name = 'usesinfobox', func = { name = tostring, params = { 'Location' }, flag = 'r' } },
		{ name = 'banktype', func = 'has_content' },
	}

	ret:defineLinks({ hide = true })

	ret:create()
	ret:cleanParams()

    ret:useSMWSubobject({
		members = 'Is members only',
		usesinfobox = 'Uses infobox',
    })

	ret:customButtonPlacement(true)
	ret:addButtonsCaption()

	ret:defineName('Infobox Location')

	ret:addRow{
		{ tag = 'argh', content = 'name', class='infobox-header', colspan = '5' }
	}
	:addRow{
		{ tag = 'argd', content = 'image', class='infobox-image infobox-full-width-content', colspan = '5' }
	}
	:pad(5)
	:addRow{
		{ tag = 'th', content = 'Released', colspan = '2' },
		{ tag = 'argd', content = 'release', colspan = '3' }
	}
	if ret:paramDefined('aka') then
		ret:addRow{
			{ tag = 'th', content = 'Also called', colspan = '2' },
			{ tag = 'argd', content = 'aka', colspan = '3' }
		}
	end
	ret:addRow{
		{ tag = 'th', content = '[[Members]]', colspan = '2' },
		{ tag = 'argd', content = 'members', colspan = '3' }
	}
	if ret:paramDefined('floors') then
		ret:addRow{
			{ tag = 'th', content = 'Floors', colspan = '2' },
			{ tag = 'argd', content = 'floors', colspan = '3' }
		}
	end
	if ret:paramDefined('location') then
		ret:addRow{
			{ tag = 'th', content = 'Location', colspan = '2' },
			{ tag = 'argd', content = 'location', colspan = '3' }
		}
	end
	if ret:paramDefined('requirement') then
		ret:addRow{
			{ tag = 'th', content = 'Requirements', colspan = '2' },
			{ tag = 'argd', content = 'requirement', colspan = '3' }
		}
	end
	if ret:paramDefined('music') then
		ret:addRow{
			{ tag = 'th', content = 'Music', colspan = '2' },
			{ tag = 'argd', content = 'music', colspan = '3' }
		}
	end
	ret:pad(5)

	local map_defined = ret:paramGrep('map', function(x) return string.lower(x or 'n/a') ~= 'n/a' end)
	if map_defined then
		ret:addRow{
			{ tag = 'th', content = 'Map', class = 'infobox-subheader', colspan = '5' }
		}
		:addRow{
			{ tag = 'argd', content = 'map', colspan = '5', class = 'infobox-full-width-content infobox-image' }
		}
	end

	if ret:paramDefined('banktype') then
		ret:addRow{
			{ tag = 'th', content = 'Advanced data', class = 'infobox-subheader', colspan = '5' },
			meta = {addClass = 'advanced-data'}
		}
		:pad(5, 'advanced-data')
		:addRow{
			{ tag = 'th', content = 'banktype', colspan = '2' },
			{ tag = 'argd', content = 'banktype',  colspan = '3' },
			meta = {addClass = 'advanced-data'}
		}
		:pad(5, 'advanced-data')
	end

	if onmain() then
		local a1 = ret:param('all')
		local a2 = ret:categoryData()
		ret:wikitext(addcategories(a1, a2))
	end
	return ret:tostring()
end

function maparg(arg)
	if not infobox.isDefined(arg) then
		return nil
	end

	-- Return images and Mapframes/NPC map unmodified
	if string.find(arg, '%[') or string.find(arg, 'mapframe') then
		return arg
	end

	return 'N/A'
end

function addcategories(args, catargs)
	local ret = { 'Locations' }

	-- Add the associated category if the parameter doesn't have content
	local notdefined_args = {
		image = 'Needs image',
		members = 'Needs members status',
		release = 'Needs release date',
		map = 'Needs map',
	}
	for n, v in pairs(notdefined_args) do
		if catargs[n] and catargs[n].all_defined == false then
			table.insert(ret, v)
		end
	end

	-- Add the associated category if the parameter does have content
	local defined_args = {
		requirement = 'Locations with requirements',
	}
	for n, v in pairs(defined_args) do
		if catargs[n] and catargs[n].one_defined then
			table.insert(ret, v)
		end
	end

	-- Add category based on banktype param
	if args['banktype'] then
		for banktype_dj in string.gmatch(args['banktype'].d or '', "[^,]+") do
			local trimmed = banktype_dj:gsub("^%s*(.-)%s*$", "%1")
			if banktype_categories[trimmed] then
				table.insert(ret, banktype_categories[trimmed])
			end
		end
		if args['banktype'].switches then
			for _, banktype_i in ipairs(args['banktype'].switches) do
				for banktype_ij in string.gmatch(banktype_i or '', "[^,]+") do
					local trimmed = banktype_ij:gsub("^%s*(.-)%s*$", "%1")
					if banktype_categories[trimmed] then
						table.insert(ret, banktype_categories[trimmed])
					end
				end
			end
		end
	end

	-- combine table and format category wikicode
	for i, v in ipairs(ret) do
		if (v ~= '') then
			ret[i] = string.format('[[Category:%s]]', v)
		end
	end

	return table.concat(ret, '')
end

return p

local p = {}
local sites = { rsc = { format = '[[classicrsw:%s]]', params = { 'rsc', 'classic', 'c' }, abbr = 'CS', title = 'The RuneScape Classic Wiki also has an article on %s.', }, rs = { format = '[[rsw:%s]]', params = { 'runescape', 'rs', 'rsw', 'rs3' }, abbr = 'RuneScape', title = 'The RuneScape Wiki also has an article on %s.', }, wp = { format = '[[wikipedia:%s]]', params = { 'wikipedia', 'wp', 'w' }, abbr = 'Wikipedia', title = 'Wikipedia also has an article on %s.', }, wg = { format = '[[meta:%s]]', params = { 'meta', 'wg' }, abbr = 'Weird Gloop', title = 'The Weird Gloop meta wiki also has an article on %s.', }, }
local order = { 'rs', 'rsc' }
local allparams = {}
function p.main(frame) local args = frame:getParent().args local pagename = mw.title.getCurrentTitle().fullText local vals = {} -- create allparams for s,t in pairs(sites) do for _,v in ipairs(t.params) do allparams[v] = s end end
-- loop named params for i,v in pairs(allparams) do if args[i] and not vals[v] then vals[v] = args[i] end end
-- loop unnamed params local i = 1 local v while args[i] do v = allparams[args[i]] if v and not vals[v] then vals[v] = pagename end i = i + 1 end
local ret = mw.html.create('div') ret:addClass('rs-external-header-links'):css('display', 'none') for _,v in ipairs(order) do if vals[v] then local span = ret:tag('span') span:wikitext(string.format(sites[v].format, vals[v])) :addClass('rs-header-icon rs-header-icon-'..v) :attr({ ['data-title'] = string.format(sites[v].title, vals[v]), ['data-site'] = v, ['data-text'] = sites[v].abbr, }) end end
return tostring(ret) end
return p

local p = {}
local CANNONBALLS = { Bronze = 43, Iron = 56, Steel = 74, Mithril = 105, Granite = 125, Adamant = 157, Rune = 201, Dragon = 270, }
local CANNONS = { Bronze = 8, Iron = 10, Steel = 12, Mithril = 15, Adamant = 23, Rune = 26, Dragon = 32, }
local HEAVY_STRENGTH_BONUS = { Bronze = 15, Iron = 30, Steel = 40, Mithril = 50, Granite = 65, Adamant = 80, Rune = 90, Dragon = 100, }
local PRAYERLIST = { ['None'] = 1.00, ['Sharp Eye'] = 1.05, ['Hawk Eye'] = 1.10, ['Eagle Eye'] = 1.15, ['Dead Eye'] = 1.18, ['Rigour'] = 1.23, }
local VOIDBONUS = { ['None'] = 1, ['Regular Void'] = 1.1, ['Elite Void'] = 1.125, }
local CREWMATES = { ['Jobless Jim'] = 1, ['Jolly Jim'] = 1, ['Sailor Jakob'] = 1, ['Ex-Captain Siad'] = 2, ['Adventurer Ada'] = 2, ['Cabin Boy Jenkins'] = 2, ['Spotter Virginia'] = 2, ['Bosun Zarah'] = 3, ['Oarswoman Olga'] = 4, ['Jittery Jim'] = 4, }
function p.main(frame) local args = frame.args or {}
local cannon_str = CANNONS[args.cannon_type or 'Bronze']
local cannonball_str = CANNONBALLS[args.cball_bronze or args.cball_iron or args.cball_steel or args.cball_mithril or args.cball_granite or args.cball_adamant or args.cball_rune or args.cball_dragon or 'Bronze']
local heavy_bonus_str = HEAVY_STRENGTH_BONUS[args.cball_bronze or args.cball_iron or args.cball_steel or args.cball_mithril or args.cball_granite or args.cball_adamant or args.cball_rune or args.cball_dragon or 'Bronze']
local max_hit = 1
if args.crew_toggle == 'Crewmate' then local eff_lvl = tonumber(args.sailing_lvl) or 99 max_hit = math.max(1, calc_max_hit_crew(eff_lvl, cannon_str, cannonball_str)) if args.perildance == 'true' then max_hit = max_hit + 1 end
local privateering_lvl = CREWMATES[args.crew_select] or 1 max_hit = math.floor(max_hit * (privateering_lvl + 13) / 20)
else local prayerbonus = PRAYERLIST[args.prayer or 'None'] local voidset = VOIDBONUS[args.void or 'None'] local gearstrengthbonus = tonumber(args.ranged_str) local eff_lvl = math.floor((math.floor((tonumber(args.ranged_lvl) or 99)*prayerbonus)+8)*voidset) max_hit = math.max(1, calc_max_hit_player(eff_lvl, cannon_str, cannonball_str, heavy_bonus_str,gearstrengthbonus))
if args.perildance == 'true' then max_hit = max_hit + 1 end end
local formatted_output = 'Cannon max hit: <b>' .. max_hit .. '<b>'
return formatted_output end
function calc_max_hit_crew(eff_lvl, cannon_str, cannonball_str) local total_str_bonus = cannon_str + cannonball_str return math.floor((eff_lvl * (total_str_bonus + 64) + 320)/640) end
function calc_max_hit_player(eff_lvl, cannon_str, cannonball_str, heavy_bonus_str,gearstrengthbonus) local total_str_bonus = cannon_str + cannonball_str + heavy_bonus_str + gearstrengthbonus return math.floor(0.5+(eff_lvl * (total_str_bonus + 64) / 640)) end
return p

