This template queries [[Bucket:locline]] and returns a maplink showing pins for all the {{T|LocLine}} coordinates written by the page given as the first unnamed parameter (can also specify <code>page_name=...</code> instead). Example:

{{T|LocLineMaplink|Eclipse red}} or equivalently {{T|LocLineMaplink|page_name=Eclipse red}} returns:

{{LocLineMaplink|Eclipse red}}
<templatedata>
{
	"params": {
		"1": {
			"description": "Page name",
			"type": "wiki-page-name",
			"required": true
		},
		"page_name": {
			"description": "Page name",
			"type": "wiki-page-name",
			"required": true
		},
		"icon": {
			"type": "string",
			"suggestedvalues": [
				"redPin, greenPin, yellowPin, magentaPin, cyanPin, bluePin, greyPin"
			],
			"default": "redPin",
			"description": "Icon symbol on the map"
		},
		"text": {
			"description": "Text shown for the maplink",
			"example": "Map, Show map",
			"type": "string",
			"default": "Map"
		},
		"mapID": {
			"description": "See RS:Map/mapIDs",
			"type": "number",
			"default": "0"
		}
	}
}
</templatedata>

