			"type": "number"
		},
		"zoom": {
			"label": "Zoom level",
			"description": "Default zoom level",
			"default": "1",
			"type": "number"
		},
		"width": {
			"label": "Map width",
			"description": "The width of the map",
			"default": "500",
			"type": "number"
		},
		"align": {
			"label": "Align",
			"description": "How to align the map",
			"type": "string",
			"default": "center"
		},
