{{Documentation}}
__notoc__
==Usage==
<pre>{{CiteDevBlog|author=|url=|title=|blogdate=|notes=|name=}}</pre>

===author===
The author of the blog found in large letters at the top. Include "Mod" prefixes, such as "Mod Mark" instead of simply "Mark".

===url===
Make sure to include the full URL, including the <nowiki>http://</nowiki>.

===title===
The title of the Developers' blog, found in large letters at the top of the page.

===blogdate===
The date the blog was added which appears right after the author's name.

{{References standard parameters}}

{{TemplateData|
<templatedata>
{
	"params": {
		"author": {
			"description": "The author of the blog",
			"example": "Mod Mark",
			"type": "string",
			"suggested": true
		},
		"url": {
			"description": "The URL of the blog",
			"example": "http://services.runescape.com/m=forum/forums.ws?380,381,370,65891449",
			"type": "url",
			"suggested": true
		},
		"name": {
			"description": "The name of the reference (to use more than once)",
			"example": "jmodtweet",
			"type": "string"
		},
		"group": {
			"description": "The group to add the reference to",
			"example": "group1",
			"type": "string"
		},
		"blogdate": {
			"description": "The date the blog was published (YYYY-MM-DD)",
			"example": "2018-05-31",
			"type": "string",
			"suggested": true
		},
		"title": {
			"description": "The name of the blog",
			"example": "Dev Blog: The Inferno",
			"type": "string",
			"suggested": true
		}
	},
	"description": "Used to create a reference to a Developer Blog on the RuneScape Forums",
	"paramOrder": [
		"author",
		"url",
		"blogdate",
		"title",
		"name",
		"group"
	],
	"format": "inline"
}
</templatedata>
}}

