==Usage==
This is used to cite comments or posts on Reddit usually made by Jagex accounts.
<pre>{{CiteReddit|author=|url=|title=|quote=|date=|archiveurl=|archivedate=|notes=|name=}}</pre>

===author===
The author of the information. Include "Mod" prefixes, such as "Mod Mark" instead of simply "Mark". Use their mod name rather than their Reddit handle.

===url===
The permalink url of the information.

===title===
The title of the Reddit post.

===quote===
Optional. The exact transcript of the relevant information.

===date===
The date the information was posted in the format: dd month yyyy.

===archiveurl===
Archive the permalink using [https://reldo.runescape.wiki/ Reldo] and insert the archived url

===archivedate===
The date the url was archived in the format: dd month yyyy.

{{References standard parameters}}
<templatedata>
{
	"params": {
		"author": {
			"description": "The author of the information",
			"example": "Mod Shauny",
			"type": "string",
			"required": true
		},
		"url": {
			"description": "The permalink url of the information",
			"example": "https://www.reddit.com/r/runescape/comments/9kqukw/runescape_wiki_leaving_wikia_now_launched_at/",
			"type": "string",
			"required": true
		},
		"title": {
			"description": "The title of the Reddit post",
			"type": "string",
			"required": true
		},
		"quote": {
			"description": "The exact transcript of the relevant information",
			"type": "string",
			"required": false
		},
		"date": {
			"description": "The date the information was posted in the format: dd month yyyy.",
			"example": "28 February 2020",
			"type": "string",
			"required": true
		},
		"archiveurl": {
			"description": "An archived link to the permalink url, usually from reldo.runescape.wiki",
            "type": "string",
			"suggested": true
		},
		"archivedate": {
			"description": "The date the url was archived in the format: dd month yyyy.",
			"type": "string",
			"suggested": true
		}
	},
	"description": "Used to create a reference to a Reddit comment or post",
	"format": "inline"
}
</templatedata>

